{
  "name": "opensip-ts-boundary-trial",
  "version": "0.3.0",
  "private": true,
  "type": "module",
  "description": "Trial TypeScript lane boundary checker (author-03 candidate). Not a product package or selected tool.",
  "bin": {
    "check-boundary": "bin/check-boundary.mjs"
  },
  "engines": {
    "node": "24.16.0"
  },
  "dependencies": {
    "enhanced-resolve": "5.25.1",
    "typescript": "6.0.3"
