#!/usr/bin/env node
// CLI entry. It always runs: there is no argv[1] self-detection, so realpath,
// /tmp-aliased and .bin symlink invocations behave identically (review-02 R1).
// Node honours the parent argument of import.meta.resolve(specifier, parent)
// only with --experimental-import-meta-resolve, so the CLI re-executes itself
// with that flag; src/resolve.mjs verifies the flag took effect before use.
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';

const FLAG = '--experimental-import-meta-resolve';
if (!process.execArgv.includes(FLAG)) {
  const self = fs.realpathSync(fileURLToPath(import.meta.url));
  const child = spawnSync(process.execPath, [FLAG, '--no-warnings', self, ...process.argv.slice(2)], { stdio: 'inherit' });
  process.exit(child.status ?? 3);
}
const { main } = await import('../src/check.mjs');
process.exitCode = await main(process.argv.slice(2));

// Lane records, the design-lock inventory join and checker-owned platform policy.
// A lane record is caller input: it lists inputs and exact trusted usages but
// cannot choose platforms, package ownership or dependency authority. Those come
// from the inventory selected by the product design lock (verified by pins) and
// from PLATFORM_POLICY below. Acceptance semantics of the selected inventory
// (review/assent chain) are owned upstream by tools/verify_design.py.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

export class LaneError extends Error {}

export const canonical = value => typeof value === 'string' && value.length > 0 && !value.includes('\\') && !value.includes('\0') &&
  !path.posix.isAbsolute(value) && !value.split('/').some(part => part === '' || part === '.' || part === '..');

// JSON with duplicate-key refusal (same rule as tools/verify_design.py).
export function strictJson(input, label) {
  const s = typeof input === 'string' ? input : input.toString('utf8');
  let i = 0;
  const fail = message => { throw new LaneError(`${label}: ${message} at offset ${i}`); };
  const ws = () => { while (i < s.length && ' \t\n\r'.includes(s[i])) i++; };
  const string = () => {
    const start = i++;
    while (i < s.length && s[i] !== '"') { if (s[i] === '\\') i++; i++; }
    if (s[i] !== '"') fail('unterminated string');
    i++;
    return JSON.parse(s.slice(start, i));
  };
  const value = () => {
    ws();
    if (s[i] === '{') {
      i++;
      const object = {};
      ws();
      if (s[i] === '}') { i++; return object; }
      for (;;) {
        ws();
        if (s[i] !== '"') fail('expected key');
        const key = string();
        if (Object.hasOwn(object, key)) fail('duplicate key ' + key);
        ws();
        if (s[i++] !== ':') fail('expected colon');
        Object.defineProperty(object, key, { value: value(), enumerable: true, writable: true, configurable: true });
        ws();
        if (s[i] === ',') { i++; continue; }
        if (s[i] === '}') { i++; return object; }
        fail('expected comma or closing brace');
      }
    }
    if (s[i] === '[') {
      i++;
      const array = [];
      ws();
      if (s[i] === ']') { i++; return array; }
      for (;;) {
        array.push(value());
        ws();
        if (s[i] === ',') { i++; continue; }
        if (s[i] === ']') { i++; return array; }
        fail('expected comma or closing bracket');
      }
    }
    if (s[i] === '"') return string();
    const token = /^(?:-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?|true|false|null)/.exec(s.slice(i, i + 64));
    if (!token) fail('invalid token');
    i += token[0].length;
    return JSON.parse(token[0]);
  };
  const result = value();
  ws();
  if (i !== s.length) fail('trailing data');
  return result;
}

const exactKeys = (object, keys, label) => {
  if (!object || typeof object !== 'object' || Array.isArray(object)) throw new LaneError(`${label} must be an object`);
  const extra = Object.keys(object).filter(key => !keys.includes(key));
  const missing = keys.filter(key => !Object.hasOwn(object, key));
  if (extra.length || missing.length) throw new LaneError(`${label} keys must be exactly ${keys.join(', ')}` + (extra.length ? `; unexpected ${extra.join(', ')}` : '') + (missing.length ? `; missing ${missing.join(', ')}` : ''));
};
const positive = value => Number.isInteger(value) && value > 0;

export function validateLaneRecord(record) {
  exactKeys(record, ['schemaVersion', 'package', 'packageRoot', 'manifest', 'tsconfig', 'inputs', 'packageManager', 'trustedUsages'], 'lane record');
  if (record.schemaVersion !== 2) throw new LaneError('lane record schemaVersion must be 2');
  if (typeof record.package !== 'string' || !record.package) throw new LaneError('lane record package must name an inventory package id');
  for (const key of ['packageRoot', 'manifest']) if (!canonical(record[key])) throw new LaneError(`lane record ${key} must be a canonical relative path`);
  if (record.tsconfig !== null && !canonical(record.tsconfig)) throw new LaneError('lane record tsconfig must be a canonical relative path or null');
  if (!Array.isArray(record.inputs) || !record.inputs.length || !record.inputs.every(canonical)) throw new LaneError('lane record inputs must be canonical relative paths');
  exactKeys(record.packageManager, ['kind', 'lockfile'], 'lane record packageManager');
  const { kind, lockfile } = record.packageManager;
  if (!['npm', 'pnpm', 'fixture-unlocked'].includes(kind)) throw new LaneError('packageManager kind must be npm, pnpm or fixture-unlocked');
  if (kind === 'fixture-unlocked' ? lockfile !== null : !canonical(lockfile)) throw new LaneError('packageManager lockfile must be a canonical path for npm/pnpm and null for fixture-unlocked');
  if (!Array.isArray(record.trustedUsages)) throw new LaneError('lane record trustedUsages must be an array');
  for (const usage of record.trustedUsages) {
    const common = ['kind', 'file', 'sha256', 'line', 'column', 'text', 'reason'];
    if (usage?.kind === 'dynamic-loader') exactKeys(usage, [...common, 'targets'], 'dynamic-loader trusted usage');
    else if (usage?.kind === 'optional-unresolved') exactKeys(usage, [...common, 'request', 'mode'], 'optional-unresolved trusted usage');
    else throw new LaneError('trusted usage kind must be dynamic-loader or optional-unresolved');
    if (!canonical(usage.file) || !/^[0-9a-f]{64}$/.test(usage.sha256) || !positive(usage.line) || !positive(usage.column) ||
      typeof usage.text !== 'string' || !usage.text || typeof usage.reason !== 'string' || !usage.reason) {
      throw new LaneError('trusted usage needs a canonical file, lowercase sha256, positive line/column, text and reason');
    }
    if (usage.kind === 'dynamic-loader' && (!Array.isArray(usage.targets) || !usage.targets.every(canonical))) throw new LaneError('dynamic-loader targets must be canonical paths');
    if (usage.kind === 'optional-unresolved' && (typeof usage.request !== 'string' || !usage.request || !['import', 'require'].includes(usage.mode))) {
      throw new LaneError('optional-unresolved usage needs a request and an import/require mode');
    }
  }
  return record;
}

function pinnedFile(architecture, pin, label) {
  exactKeys(pin, ['path', 'sha256', 'bytes'], label);
  if (!canonical(pin.path) || !/^[0-9a-f]{64}$/.test(pin.sha256) || !Number.isInteger(pin.bytes) || pin.bytes < 0) throw new LaneError(`${label} pin is malformed`);
  let current = architecture;
  for (const part of pin.path.split('/')) {
    current = path.join(current, part);
    const stat = fs.lstatSync(current, { throwIfNoEntry: false });
    if (!stat) throw new LaneError(`${label} pinned file missing: ${pin.path}`);
    if (stat.isSymbolicLink()) throw new LaneError(`${label} pinned path contains a symlink: ${pin.path}`);
  }
  const raw = fs.readFileSync(current);
  if (raw.length !== pin.bytes || crypto.createHash('sha256').update(raw).digest('hex') !== pin.sha256) throw new LaneError(`${label} pinned bytes differ: ${pin.path}`);
  return raw;
}

export function bindInventory({ architecture, designLock }) {
  const lockRaw = fs.readFileSync(designLock);
  const lock = strictJson(lockRaw, 'design lock');
  const successors = lock.inventorySuccessors;
  if (!Array.isArray(successors) || !successors.length) throw new LaneError('design lock selects no inventory successor');
  const binding = successors[successors.length - 1];
  exactKeys(binding, ['parent', 'candidate', 'record', 'review', 'assent'], 'inventory successor binding');
  const raw = {};
  for (const key of Object.keys(binding)) raw[key] = pinnedFile(architecture, binding[key], `inventory ${key}`);
  const inputs = Array.isArray(lock.inputs) ? lock.inputs : [];
  if (!inputs.some(row => row && row.path === binding.parent.path && row.sha256 === binding.parent.sha256 && row.bytes === binding.parent.bytes)) {
    throw new LaneError('inventory parent is not a selected design-lock input');
  }
  const inventory = strictJson(raw.candidate, 'selected inventory');
  if (!Array.isArray(inventory.packages) || !Array.isArray(inventory.files)) throw new LaneError('selected inventory lacks packages or files');
  return {
    designLockSha256: crypto.createHash('sha256').update(lockRaw).digest('hex'),
    selectedInventory: binding.candidate,
    pinsVerified: Object.keys(binding),
    inventoryStanding: inventory.standing,
    acceptanceChain: 'pins verified by bytes; review/assent semantics are owned by tools/verify_design.py and are not re-evaluated here',
    inventory,
  };
}

const RUNTIME = ['dependencies', 'optionalDependencies', 'peerDependencies'];
const ALL = [...RUNTIME, 'devDependencies'];

// Checker-owned platform policy keyed by inventory package id (chapter 14 and
// the build plan's lane table). Groups are matched in order against the path
// relative to the package root; the first match wins.
export const PLATFORM_POLICY = {
  report: [
    { name: 'browser-runtime', platform: 'browser', match: rel => rel.startsWith('src/'), runtimeClasses: RUNTIME },
    { name: 'node-build-scripts', platform: 'node', match: () => true, runtimeClasses: ALL },
  ],
  'typescript-provider': [
    { name: 'node-build-scripts', platform: 'node', match: rel => rel.startsWith('scripts/'), runtimeClasses: ALL },
    { name: 'node-provider-runtime', platform: 'node', match: () => true, runtimeClasses: RUNTIME },
  ],
  tooling: [
    { name: 'node-tooling', platform: 'node', match: () => true, runtimeClasses: ALL },
  ],
};

export function resolveLane({ record, binding, unboundKind }) {
  const pkg = binding.inventory.packages.find(p => p && p.id === record.package);
  const boundMatch = pkg && pkg.path === record.packageRoot && ['typescript-package', 'tooling'].includes(pkg.kind);
  let standing;
  let policyId;
  if (boundMatch) {
    standing = 'bound';
    policyId = pkg.id;
  } else if (unboundKind) {
    if (binding.inventory.packages.some(p => p && p.path === record.packageRoot)) throw new LaneError('unbound trial lanes cannot shadow an inventory package root');
    if (unboundKind !== 'tooling' || record.package !== 'tooling') throw new LaneError('only tooling lanes may run unbound, and they must name package tooling');
    standing = 'unbound-trial';
    policyId = 'tooling';
  } else {
    throw new LaneError(`lane ${record.package} at ${record.packageRoot} is not a typescript-package or tooling package of the selected inventory`);
  }
  if (!PLATFORM_POLICY[policyId]) throw new LaneError(`no platform policy for inventory package ${policyId}`);
  const inventoryDependencies = pkg && boundMatch ? pkg.dependencies : [];
  const rows = boundMatch ? binding.inventory.files.filter(f => f.package === pkg.id).map(f => f.path) : [];
  return { standing, policyId, groups: PLATFORM_POLICY[policyId], inventoryDependencies, inventoryRows: rows };
}

export function localPackageNames(root, binding, ownManifest) {
  const names = new Set();
  for (const pkg of binding.inventory.packages) {
    if (!pkg || !['typescript-package', 'tooling'].includes(pkg.kind) || typeof pkg.path !== 'string') continue;
    const manifest = path.join(root, pkg.path, 'package.json');
    if (!fs.existsSync(manifest)) continue;
    try {
      const name = JSON.parse(fs.readFileSync(manifest, 'utf8')).name;
      if (typeof name === 'string') names.add(name);
    } catch { /* other lanes' malformed manifests do not block this lane */ }
  }
  if (typeof ownManifest.name === 'string') names.add(ownManifest.name);
  return names;
}

// Module-request extraction from TypeScript's parser. Build usages feed the
// TypeScript resolver; runtime usages come from JavaScript text (emitted by
// TypeScript for own TS sources, or materialized files) and feed Node or the
// declared browser resolver. Extraction never resolves or executes anything.
import ts from 'typescript';

const literal = node => !!node && (ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node));
const isIdent = (node, text) => !!node && ts.isIdentifier(node) && node.text === text;
const member = (node, object, name) => !!node && ts.isPropertyAccessExpression(node) && isIdent(node.expression, object) && node.name.text === name;

export const scriptKindFor = file => /\.tsx$/.test(file) ? ts.ScriptKind.TSX
  : /\.(?:d\.)?[cm]?ts$/.test(file) ? ts.ScriptKind.TS
  : /\.jsx$/.test(file) ? ts.ScriptKind.JSX
  : /\.json$/.test(file) ? ts.ScriptKind.JSON : ts.ScriptKind.JS;

export function parse(fileName, text, scriptKind = scriptKindFor(fileName)) {
  return ts.createSourceFile(fileName, text, ts.ScriptTarget.Latest, true, scriptKind);
}

export function where(sf, node) {
  const { line, character } = sf.getLineAndCharacterOfPosition(node.getStart(sf));
  return { line: line + 1, column: character + 1 };
}

function guardedByTry(node) {
  for (let current = node; current.parent; current = current.parent) {
    if (ts.isFunctionLike(current)) return false;
    if (ts.isTryStatement(current.parent) && current.parent.tryBlock === current) return true;
  }
  return false;
}

const hasExportModifier = statement => ts.canHaveModifiers(statement) && (ts.getModifiers(statement) ?? []).some(m => m.kind === ts.SyntaxKind.ExportKeyword);

export function runtimeUsages(sf) {
  const requests = [];
  const loaders = [];
  const unsupported = [];
  const assets = [];
  let esmSyntax = sf.statements.some(s => ts.isImportDeclaration(s) || ts.isExportDeclaration(s) || ts.isExportAssignment(s) || hasExportModifier(s));
  let requireCalls = false;
  let declaresRequire = false;
  const add = (list, node, extra) => list.push({ ...where(sf, node), text: node.getText(sf), guarded: guardedByTry(node), ...extra });
  const callOf = node => node.parent && ts.isCallExpression(node.parent) && node.parent.expression === node;

  const visit = node => {
    if (ts.isImportDeclaration(node)) {
      if (!node.importClause?.isTypeOnly) {
        if (literal(node.moduleSpecifier)) add(requests, node.moduleSpecifier, { kind: 'import', mode: 'import', request: node.moduleSpecifier.text });
        else add(loaders, node, { kind: 'computed-import' });
      }
    } else if (ts.isExportDeclaration(node) && node.moduleSpecifier && !node.isTypeOnly && literal(node.moduleSpecifier)) {
      add(requests, node.moduleSpecifier, { kind: 'export', mode: 'import', request: node.moduleSpecifier.text });
    } else if (ts.isMetaProperty(node) && node.keywordToken === ts.SyntaxKind.ImportKeyword) {
      esmSyntax = true;
    } else if (ts.isAwaitExpression(node) && !ts.findAncestor(node.parent, ts.isFunctionLike)) {
      esmSyntax = true;
    } else if (ts.isCallExpression(node)) {
      const callee = node.expression;
      const [first] = node.arguments;
      if (callee.kind === ts.SyntaxKind.ImportKeyword) {
        if (literal(first)) add(requests, first, { kind: 'dynamic-import', mode: 'import', request: first.text });
        else add(loaders, node, { kind: 'computed-import' });
      } else if (isIdent(callee, 'require') && first && ts.isArrayLiteralExpression(first)) {
        add(unsupported, node, { kind: 'amd-require' });
      } else if (isIdent(callee, 'require')) {
        requireCalls = true;
        if (literal(first)) add(requests, first, { kind: 'require', mode: 'require', request: first.text });
        else add(loaders, node, { kind: 'computed-require' });
      } else if (member(callee, 'require', 'resolve') || member(callee, 'module', 'require')) {
        requireCalls = true;
        const kind = callee.name.text === 'resolve' ? 'require-resolve' : 'module-require';
        if (literal(first)) add(requests, first, { kind, mode: 'require', request: first.text });
        else add(loaders, node, { kind: 'computed-require' });
      } else if (ts.isPropertyAccessExpression(callee) && callee.name.text === 'getBuiltinModule' &&
        (isIdent(callee.expression, 'process') || member(callee.expression, 'globalThis', 'process'))) {
        if (literal(first)) add(requests, first, { kind: 'get-builtin-module', mode: 'require', request: first.text, builtinOnly: true });
        else add(loaders, node, { kind: 'computed-builtin' });
      } else if (isIdent(callee, 'define') && node.arguments.some(a => ts.isArrayLiteralExpression(a) || ts.isFunctionExpression(a))) {
        add(unsupported, node, { kind: 'amd-define' });
      } else if (isIdent(callee, 'createRequire') || (ts.isPropertyAccessExpression(callee) && callee.name.text === 'createRequire')) {
        add(loaders, node, { kind: 'create-require' });
      } else if (isIdent(callee, 'eval') || isIdent(callee, 'Function')) {
        add(loaders, node, { kind: 'eval', declaredInputsOnly: true });
      }
    } else if (ts.isNewExpression(node)) {
      const [first, second] = node.arguments ?? [];
      if (isIdent(node.expression, 'Function')) {
        add(loaders, node, { kind: 'eval', declaredInputsOnly: true });
      } else if (isIdent(node.expression, 'URL') && second && ts.isPropertyAccessExpression(second) && ts.isMetaProperty(second.expression) && second.name.text === 'url') {
        if (literal(first)) add(assets, first, { kind: 'asset-url', request: first.text });
        else add(loaders, node, { kind: 'computed-asset-url' });
      } else if ((isIdent(node.expression, 'Worker') || isIdent(node.expression, 'SharedWorker')) && literal(first)) {
        add(assets, first, { kind: 'worker-path', request: first.text });
      }
    } else if (ts.isElementAccessExpression(node) && (isIdent(node.expression, 'require') || isIdent(node.expression, 'module'))) {
      add(loaders, node, { kind: 'computed-member' });
    }

    if (ts.isIdentifier(node) && node.text === 'require') {
      const p = node.parent;
      const declaration = (ts.isVariableDeclaration(p) || ts.isParameter(p) || ts.isFunctionDeclaration(p) || ts.isBindingElement(p)) && p.name === node;
      if (declaration) declaresRequire = true;
      const propertyName = (ts.isPropertyAccessExpression(p) || ts.isPropertyAssignment(p) || ts.isMethodDeclaration(p) || ts.isPropertyDeclaration(p) ||
        ts.isPropertySignature(p) || ts.isMethodSignature(p) || ts.isQualifiedName(p)) && p.name === node;
      const memberRead = ts.isPropertyAccessExpression(p) && p.expression === node &&
        (['main', 'cache', 'extensions'].includes(p.name.text) || (p.name.text === 'resolve' && callOf(p)));
      const allowed = declaration || propertyName || memberRead || callOf(node) || ts.isTypeOfExpression(p) || ts.isArrayLiteralExpression(p) && p.parent && ts.isCallExpression(p.parent) && isIdent(p.parent.expression, 'define');
      const unCalledModuleRequire = ts.isPropertyAccessExpression(p) && p.name === node && isIdent(p.expression, 'module') && !callOf(p);
      if (!allowed || unCalledModuleRequire) add(loaders, node, { kind: 'require-alias' });
    }
    ts.forEachChild(node, visit);
  };
  visit(sf);
  return { requests, loaders, unsupported, assets, esmSyntax, requireCalls, declaresRequire };
}

// Requests TypeScript resolves when building a program for this file.
export function buildUsages(sf) {
  const usages = [];
  const js = /\.[cm]?jsx?$/.test(sf.fileName);
  const isModuleFile = sf.statements.some(s => ts.isImportDeclaration(s) || ts.isExportDeclaration(s) || ts.isExportAssignment(s) || ts.isImportEqualsDeclaration(s) || hasExportModifier(s));
  const add = (node, kind, typeOnly) => usages.push({ node, kind, request: node.text, typeOnly, ...where(sf, node) });
  const visitDoc = node => {
    if (ts.isImportTypeNode(node) && ts.isLiteralTypeNode(node.argument) && literal(node.argument.literal)) add(node.argument.literal, 'jsdoc-import-type', true);
    else if (ts.isJSDocImportTag && ts.isJSDocImportTag(node) && literal(node.moduleSpecifier)) add(node.moduleSpecifier, 'jsdoc-import-tag', true);
    ts.forEachChild(node, visitDoc);
  };
  const visit = node => {
    if (ts.isImportDeclaration(node) && literal(node.moduleSpecifier)) add(node.moduleSpecifier, 'import', !!node.importClause?.isTypeOnly);
    else if (ts.isExportDeclaration(node) && node.moduleSpecifier && literal(node.moduleSpecifier)) add(node.moduleSpecifier, 'export', node.isTypeOnly);
    else if (ts.isImportEqualsDeclaration(node) && ts.isExternalModuleReference(node.moduleReference) && literal(node.moduleReference.expression)) add(node.moduleReference.expression, 'import-equals', node.isTypeOnly);
    else if (ts.isImportTypeNode(node) && ts.isLiteralTypeNode(node.argument) && literal(node.argument.literal)) add(node.argument.literal, 'import-type', true);
    else if (ts.isCallExpression(node) && node.expression.kind === ts.SyntaxKind.ImportKeyword && literal(node.arguments[0])) add(node.arguments[0], 'dynamic-import', false);
    else if (js && ts.isCallExpression(node) && isIdent(node.expression, 'require') && node.arguments.length === 1 && literal(node.arguments[0])) add(node.arguments[0], 'require', false);
    else if (ts.isModuleDeclaration(node) && ts.isStringLiteral(node.name) && isModuleFile) add(node.name, 'augmentation', true);
    if (js) for (const tag of ts.getJSDocTags(node)) visitDoc(tag);
    ts.forEachChild(node, visit);
  };
  visit(sf);
  return usages;
}

// Resolver adapters. Each graph has one authority and nothing is executed:
//   Node runtime  -> Node 24's own resolvers: createRequire(parent).resolve
//                    (checks existence) and import.meta.resolve(specifier, parent)
//                    followed by an explicit regular-file check, because
//                    import.meta.resolve does not check that its result exists.
//   browser       -> enhanced-resolve, configured as the declared bundler policy.
// TypeScript build resolution is called directly from check.mjs.
import fs from 'node:fs';
import path from 'node:path';
import { createRequire, isBuiltin } from 'node:module';
import { pathToFileURL, fileURLToPath } from 'node:url';
import enhancedResolve from 'enhanced-resolve';

export function assertImportMetaResolveParent() {
  const probe = import.meta.resolve('./probe.mjs', 'file:///opensip-boundary-probe/base/');
  if (probe !== 'file:///opensip-boundary-probe/base/probe.mjs') {
    throw new Error('import.meta.resolve ignores its parent argument; run under --experimental-import-meta-resolve (bin/check-boundary.mjs does this)');
  }
}

const TYPE_STRIPPED = /\.(?:[cm]?ts|tsx)$/;
const IN_NODE_MODULES = /[\\/]node_modules[\\/]/;

export function nodeResolve(request, baseFile, mode) {
  if (isBuiltin(request)) return { core: true, resolved: request };
  if (mode === 'require') {
    try {
      const result = createRequire(baseFile).resolve(request);
      if (isBuiltin(result)) return { core: true, resolved: result };
      return loadable(fs.realpathSync(result));
    } catch (error) {
      const relative = request.startsWith('./') || request.startsWith('../');
      return { error: error.code ?? 'ERR_RESOLVE', candidate: relative ? path.resolve(path.dirname(baseFile), request) : undefined };
    }
  }
  let url;
  try {
    url = import.meta.resolve(request, pathToFileURL(baseFile).href);
  } catch (error) {
    return { error: error.code ?? 'ERR_RESOLVE' };
  }
  if (url.startsWith('node:')) return { core: true, resolved: url };
  if (!url.startsWith('file:')) return { error: 'ERR_UNSUPPORTED_ESM_URL_SCHEME', url };
  const candidate = fileURLToPath(url);
  const stat = fs.statSync(candidate, { throwIfNoEntry: false });
  if (!stat) return { error: 'ERR_MODULE_NOT_FOUND', candidate };
  if (stat.isDirectory()) return { error: 'ERR_UNSUPPORTED_DIR_IMPORT', candidate };
  if (!stat.isFile()) return { error: 'ERR_MODULE_NOT_FOUND', candidate };
  return loadable(fs.realpathSync(candidate));
}

// Node 24 refuses type stripping for files under node_modules even when resolution succeeds.
function loadable(file) {
  if (TYPE_STRIPPED.test(file) && IN_NODE_MODULES.test(file)) return { error: 'ERR_UNSUPPORTED_NODE_MODULES_TYPE_STRIPPING', candidate: file };
  return { resolved: file };
}

// Node's package scope: nearest package.json, not crossing a node_modules directory.
// (module.findPackageJSON requires an existing module; emitted outputs may not exist.)
export function packageScope(file) {
  for (let dir = path.dirname(file); ; dir = path.dirname(dir)) {
    if (path.basename(dir) === 'node_modules') return { type: undefined };
    const manifest = path.join(dir, 'package.json');
    if (fs.existsSync(manifest)) {
      try {
        const parsed = JSON.parse(fs.readFileSync(manifest, 'utf8'));
        return { manifest, type: parsed.type };
      } catch {
        return { manifest, invalid: true };
      }
    }
    if (path.dirname(dir) === dir) return { type: undefined };
  }
}

export function nodeFormat(location, usages) {
  if (location.endsWith('.mjs')) return 'module';
  if (location.endsWith('.cjs')) return 'commonjs';
  const scope = packageScope(location);
  if (scope.invalid) return 'invalid-package-scope';
  if (scope.type === 'module') return 'module';
  if (scope.type === 'commonjs') return 'commonjs';
  if (/\.jsx?$/.test(location)) {
    // Node 24 detects module syntax in .js files whose scope has no "type" field.
    if (usages.esmSyntax && usages.requireCalls && !usages.declaresRequire) return 'ambiguous';
    if (usages.esmSyntax) return 'module';
  }
  return 'commonjs';
}

// Declared browser bundler policy (bundler unselected): browser + per-usage
// import/require + module + default conditions, browser/module/main fields,
// the browser alias field and package exports/imports.
export function createBrowserResolvers() {
  const fileSystem = new enhancedResolve.CachedInputFileSystem(fs, 4000);
  const make = mode => enhancedResolve.ResolverFactory.createResolver({
    fileSystem, useSyncFileSystemCalls: true, symlinks: true, fullySpecified: false,
    conditionNames: ['browser', mode, 'module', 'default'],
    mainFields: ['browser', 'module', 'main'], aliasFields: ['browser'],
    exportsFields: ['exports'], importsFields: ['imports'],
    extensions: ['.js', '.mjs', '.cjs', '.json'],
  });
  return { import: make('import'), require: make('require') };
}

export function browserResolve(resolvers, request, baseFile, mode) {
  try {
    const result = resolvers[mode].resolveSync({}, path.dirname(baseFile), request);
    if (result === false) return { ignored: true };
    return { resolved: fs.realpathSync(result) };
  } catch (error) {
    const relative = request.startsWith('./') || request.startsWith('../');
    if (isBuiltin(request)) return { core: true, resolved: request };
    return { error: 'ERR_BROWSER_POLICY_UNRESOLVED', candidate: relative ? path.resolve(path.dirname(baseFile), request) : undefined, message: String(error.message).split('\n')[0] };
  }
}

// Trial TypeScript lane boundary checker (author-03). Resolver authorities:
//   build/declaration graph -> TypeScript 6.0.3 program, lane tsconfig and
//                              program.getModeForUsageLocation per usage;
//   Node runtime graph      -> Node 24 non-executing resolvers over TypeScript-
//                              emitted JavaScript (type-only imports erased by the
//                              emitter) and materialized JavaScript;
//   browser runtime graph   -> enhanced-resolve as the declared bundler policy.
// Nothing is executed. Static literal requests only: unsupported forms are
// refused unless an exact trusted-usage record matches.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { isBuiltin } from 'node:module';
import ts from 'typescript';
import { LaneError, validateLaneRecord, bindInventory, resolveLane, localPackageNames, strictJson } from './lane.mjs';
import { parse, runtimeUsages, buildUsages } from './usages.mjs';
import { assertImportMetaResolveParent, nodeResolve, nodeFormat, createBrowserResolvers, browserResolve } from './resolve.mjs';

const TOOL_VERSION = '0.3.0';
const TS_SOURCE = /\.(?:tsx|[cm]?ts)$/;
const DECLARATION = /\.d\.[cm]?ts$/;
const JS_FILE = /\.[cm]?jsx?$/;
const SCANNABLE = /\.(?:[cm]?[jt]sx?)$/;
const EXTERNAL = /(?:^|\/)node_modules\//;
const DEPENDENCY_CLASSES = ['dependencies', 'optionalDependencies', 'peerDependencies', 'devDependencies'];

const sha256 = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const isBare = request => !request.startsWith('.') && !request.startsWith('/') && !request.startsWith('#') && !/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(request);
const packageName = request => request.startsWith('@') ? request.split('/').slice(0, 2).join('/') : request.split('/')[0];
const within = (rel, dir) => rel === dir || rel.startsWith(dir + '/');

export async function checkBoundary({ root, record, designLock, architecture, unboundKind }) {
  const started = process.hrtime.bigint();
  assertImportMetaResolveParent();
  validateLaneRecord(record);
  if (typeof root !== 'string' || !fs.statSync(root, { throwIfNoEntry: false })?.isDirectory()) throw new LaneError('root must be an existing directory');
  root = fs.realpathSync(root);
  const binding = bindInventory({ architecture, designLock });
  const lane = resolveLane({ record, binding, unboundKind });
  const rel = abs => path.relative(root, abs).split(path.sep).join('/');
  const abs = relPath => path.join(root, relPath);
  const own = record.packageRoot;
  const refusals = [];
  const refuse = (category, detail) => refusals.push({ category, ...detail });
  const inputs = new Set(record.inputs);

  // ---- declared inputs, manifest, package-source census ----
  for (const file of [...record.inputs, record.manifest, ...(record.tsconfig ? [record.tsconfig] : [])]) {
    if (!within(file, own) || EXTERNAL.test(file)) refuse('input-path', { file, message: 'declared file outside lane package or under node_modules' });
    let current = root;
    for (const part of file.split('/')) {
      current = path.join(current, part);
      const stat = fs.lstatSync(current, { throwIfNoEntry: false });
      if (!stat) { refuse('unresolved', { file, message: 'declared file missing' }); break; }
      if (stat.isSymbolicLink()) { refuse('input-path', { file, message: 'symlink in declared file path' }); break; }
    }
  }
  if (record.inputs.length !== inputs.size) refuse('input-path', { message: 'duplicate declared input' });
  if (refusals.length) return finish();
  const manifest = strictJson(fs.readFileSync(abs(record.manifest)), record.manifest);
  const localNames = localPackageNames(root, binding, manifest);
  const walkSources = dir => fs.readdirSync(abs(dir), { withFileTypes: true }).flatMap(entry => {
    const child = `${dir}/${entry.name}`;
    if (entry.isDirectory()) return entry.name === 'node_modules' ? [] : walkSources(child);
    return SCANNABLE.test(entry.name) ? [child] : [];
  });
  for (const file of walkSources(own)) if (!inputs.has(file)) refuse('undeclared-local', { file, message: 'package source not declared as a lane input' });
  const inventoryRowsPresent = lane.inventoryRows.filter(row => SCANNABLE.test(row) && fs.existsSync(abs(row)));
  const unboundInputs = record.inputs.filter(file => !lane.inventoryRows.includes(file));

  // ---- package manager topology ----
  const topology = { kind: record.packageManager.kind, lockfile: record.packageManager.lockfile };
  if (record.packageManager.lockfile) {
    const lockPath = abs(record.packageManager.lockfile);
    if (!fs.existsSync(lockPath)) refuse('topology', { message: 'declared lockfile missing ' + record.packageManager.lockfile });
    else topology.lockfileSha256 = sha256(fs.readFileSync(lockPath));
    if (record.packageManager.kind === 'pnpm') {
      const modulesYaml = path.join(path.dirname(lockPath), 'node_modules', '.modules.yaml');
      const text = fs.existsSync(modulesYaml) ? fs.readFileSync(modulesYaml, 'utf8') : '';
      topology.pnpm = { packageManager: /"packageManager": "([^"]+)"/.exec(text)?.[1], nodeLinker: /"nodeLinker": "([^"]+)"/.exec(text)?.[1] };
      if (!topology.pnpm.packageManager?.startsWith('pnpm@')) refuse('topology', { message: 'pnpm lane without a pnpm-materialized node_modules/.modules.yaml' });
      if (manifest.packageManager && manifest.packageManager !== topology.pnpm.packageManager) refuse('topology', { message: `manifest packageManager ${manifest.packageManager} differs from materialization ${topology.pnpm.packageManager}` });
    }
  }

  // ---- TypeScript configuration and program ----
  let parsed;
  let program;
  let options;
  const plannedOutputs = new Map();
  const emitted = new Map();
  const tsInputs = record.inputs.filter(file => TS_SOURCE.test(file) && !DECLARATION.test(file));
  if (record.tsconfig) {
    const reads = new Set();
    const host = {
      ...ts.sys,
      readFile(file) { const raw = ts.sys.readFile(file); if (raw !== undefined) reads.add(path.resolve(file)); return raw; },
      onUnRecoverableConfigFileDiagnostic(d) { refuse('config-invalid', { message: ts.flattenDiagnosticMessageText(d.messageText, '\n') }); },
    };
    parsed = ts.getParsedCommandLineOfConfigFile(abs(record.tsconfig), {}, host);
    if (parsed) {
      for (const d of parsed.errors) refuse('config-invalid', { message: ts.flattenDiagnosticMessageText(d.messageText, '\n') });
      if (parsed.projectReferences?.length) refuse('config-invalid', { message: 'project references are not selected' });
      if (parsed.options.plugins?.length) refuse('config-invalid', { message: 'compiler plugins are not selected' });
      if (parsed.options.outFile) refuse('config-invalid', { message: 'outFile concatenation is not selected' });
      if (parsed.options.typeRoots !== undefined) refuse('ambient-types', { message: 'typeRoots is not selected' });
      if (!Array.isArray(parsed.options.types)) refuse('ambient-types', { message: 'compilerOptions.types must be explicit' });
      for (const read of reads) {
        const physical = rel(fs.realpathSync(read));
        if (!EXTERNAL.test(physical) && !within(physical, own)) refuse('config-owner', { file: physical, message: 'configuration read outside the lane package' });
      }
      for (const file of parsed.fileNames) if (!inputs.has(rel(path.resolve(file)))) refuse('config-include', { file: rel(file), message: 'tsconfig selects an undeclared input' });
      for (const name of parsed.options.types ?? []) {
        const typesPackage = name.startsWith('@types/') ? name : '@types/' + name.replace(/^@/, '').replace('/', '__');
        if (!DEPENDENCY_CLASSES.some(key => manifest[key]?.[typesPackage] !== undefined || manifest[key]?.[name] !== undefined)) refuse('ambient-types', { request: name, message: 'ambient type package not declared by the lane manifest' });
        if (lane.groups.some(g => g.platform === 'browser') && (name === 'node' || name === '@types/node')) refuse('browser-node', { request: name, message: 'browser lane selects Node ambient types' });
      }
      options = { ...parsed.options, allowJs: true, checkJs: false, noEmit: false, emitDeclarationOnly: false, declaration: false, declarationMap: false,
        sourceMap: false, inlineSourceMap: false, composite: false, incremental: false, noEmitOnError: false };
      const compilerHost = ts.createCompilerHost(options, true);
      program = ts.createProgram({ rootNames: record.inputs.filter(f => SCANNABLE.test(f)).map(abs), options, host: compilerHost });
      for (const file of record.inputs.filter(f => SCANNABLE.test(f))) {
        const sf = program.getSourceFile(abs(file));
        const diagnostics = sf ? program.getSyntacticDiagnostics(sf) : [];
        if (!sf) refuse('parse-failure', { file, message: 'compiler did not load declared input' });
        else if (diagnostics.length) refuse('parse-failure', { file, message: ts.flattenDiagnosticMessageText(diagnostics[0].messageText, '\n') });
      }
      for (const file of tsInputs) {
        const sf = program.getSourceFile(abs(file));
        if (!sf) continue;
        for (const output of ts.getOutputFileNames({ ...parsed, options }, abs(file), !ts.sys.useCaseSensitiveFileNames)) {
          if (JS_FILE.test(output)) plannedOutputs.set(path.resolve(output), abs(file));
        }
        program.emit(sf, (fileName, text) => { if (JS_FILE.test(fileName)) emitted.set(abs(file), { location: path.resolve(fileName), text }); }, undefined, false);
      }
    }
  } else if (tsInputs.length) {
    refuse('config-invalid', { message: 'TypeScript inputs require a lane tsconfig' });
  }

  const groupOf = file => lane.groups.find(g => g.match(file.slice(own.length + 1)));
  const edges = [];
  const trustedApplied = new Set();
  const reachedLocal = new Set();

  // ---- edge policy (shared by all graphs) ----
  function evaluate(edge, group) {
    edges.push(edge);
    const fromExternal = EXTERNAL.test(edge.from);
    if (edge.core) {
      if (group?.platform === 'browser' && (edge.graph === 'runtime' || !fromExternal)) refuse('browser-node', edgeDetail(edge, 'Node built-in reached from browser code'));
      return false;
    }
    if (edge.ignored) return false;
    if (!edge.resolved) {
      if (edge.graph === 'runtime' && matchTrusted('optional-unresolved', edge)) return false;
      refuse('unresolved', edgeDetail(edge, edge.error ?? 'unresolved request'));
      return false;
    }
    const target = edge.resolved;
    if (target.startsWith('../')) { refuse('outside-root', edgeDetail(edge, 'target outside the checked root')); return false; }
    const targetExternal = EXTERNAL.test(target);
    const requestName = isBare(edge.request) ? packageName(edge.request) : undefined;
    let traverse = true;
    if (!fromExternal) {
      if (targetExternal) {
        if (!requestName) refuse('external-by-path', edgeDetail(edge, 'own source reaches materialized dependency files by path'));
        else declared(edge, group, requestName);
      } else if (!within(target, own)) {
        refuse('lane-escape', edgeDetail(edge, 'own source reaches another package'));
        traverse = false;
      } else if (requestName && requestName !== manifest.name) {
        refuse('lane-escape', edgeDetail(edge, 'bare request resolved to lane source under a different package name'));
      }
      if (requestName && localNames.has(requestName) && requestName !== manifest.name && targetExternal) refuse('local-name-shadow', edgeDetail(edge, 'local package name realized from materialized dependencies'));
    } else {
      const materialized = target.startsWith('node_modules/') || (within(target, own) && EXTERNAL.test(target.slice(own.length + 1)));
      if (!targetExternal || !materialized) { refuse('reentry', edgeDetail(edge, 'materialized dependency reaches repository sources or another package installation')); traverse = false; }
      if (requestName && localNames.has(requestName)) refuse('local-name-shadow', edgeDetail(edge, 'dependency requests a local package name'));
    }
    if (targetExternal) {
      const segments = target.split('/');
      const index = segments.lastIndexOf('node_modules');
      const dirName = segments[index + 1]?.startsWith('@') ? segments.slice(index + 1, index + 3).join('/') : segments[index + 1];
      if (localNames.has(dirName)) refuse('local-name-shadow', edgeDetail(edge, 'materialized package directory uses a local package name'));
    } else {
      reachedLocal.add(target);
    }
    return traverse;
  }

  function declared(edge, group, name) {
    const spec = DEPENDENCY_CLASSES.map(key => [key, manifest[key]?.[name]]).find(([, value]) => value !== undefined);
    const typesName = '@types/' + name.replace(/^@/, '').replace('/', '__');
    const typesSpec = edge.graph === 'build' ? DEPENDENCY_CLASSES.map(key => manifest[key]?.[typesName]).find(v => v !== undefined) : undefined;
    if (!spec && !typesSpec) { refuse('undeclared-external', edgeDetail(edge, `package ${name} is not declared by ${record.manifest}`)); return; }
    if (spec && typeof spec[1] === 'string' && spec[1].startsWith('npm:')) {
      const aliased = spec[1].slice(4).replace(/@[^@]*$/, '');
      if (localNames.has(name) || localNames.has(aliased)) refuse('local-name-shadow', edgeDetail(edge, `npm alias ${name} -> ${spec[1]} involves a local package name`));
    }
    if (edge.graph === 'runtime' && spec && group && !group.runtimeClasses.includes(spec[0])) refuse('runtime-dev-dependency', edgeDetail(edge, `${name} is only a ${spec[0]} entry but is reached by ${group.name}`));
  }

  const edgeDetail = (edge, message) => ({ graph: edge.graph, group: edge.group, from: edge.from, line: edge.line, column: edge.column, request: edge.request, mode: edge.mode, resolved: edge.resolved, message });

  function matchTrusted(kind, usage) {
    for (const [index, trusted] of record.trustedUsages.entries()) {
      if (trusted.kind !== kind || trusted.file !== usage.from || trusted.line !== usage.line || trusted.column !== usage.column || trusted.text !== usage.text) continue;
      if (trusted.sha256 !== sha256(fs.readFileSync(abs(usage.from)))) continue;
      if (kind === 'optional-unresolved' && (trusted.request !== usage.request || trusted.mode !== usage.mode || !usage.guarded)) continue;
      trustedApplied.add(index);
      return trusted;
    }
    return undefined;
  }

  // ---- build/declaration graph (TypeScript resolver) ----
  if (program) {
    const host = ts.createCompilerHost(options, true);
    const cache = ts.createModuleResolutionCache(root, name => ts.sys.useCaseSensitiveFileNames ? name : name.toLowerCase(), options);
    const explained = new Set(record.inputs.map(abs));
    for (const sf of program.getSourceFiles()) {
      if (program.isSourceFileDefaultLibrary(sf)) continue;
      const from = rel(sf.fileName);
      const group = EXTERNAL.test(from) ? undefined : groupOf(from);
      for (const usage of buildUsages(sf)) {
        const edge = { graph: 'build', group: group?.name, from, kind: usage.kind, request: usage.request, line: usage.line, column: usage.column, typeOnly: usage.typeOnly };
        if (isBuiltin(usage.request)) { evaluate({ ...edge, core: true }, group); continue; }
        const mode = program.getModeForUsageLocation(sf, usage.node);
        edge.mode = mode === ts.ModuleKind.ESNext ? 'import' : mode === ts.ModuleKind.CommonJS ? 'require' : 'unspecified';
        const result = ts.resolveModuleName(usage.request, sf.fileName, options, host, cache, undefined, mode).resolvedModule;
        if (result) {
          const physical = fs.realpathSync(result.resolvedFileName);
          explained.add(physical);
          edge.resolved = rel(physical);
        } else if (usage.kind === 'augmentation') {
          continue; // an augmentation of an ambient module name is not a file request
        } else {
          edge.error = 'TypeScript could not resolve the request';
        }
        evaluate(edge, group);
      }
      for (const reference of sf.referencedFiles) {
        const target = path.resolve(path.dirname(sf.fileName), reference.fileName);
        const exists = fs.existsSync(target);
        if (exists) explained.add(fs.realpathSync(target));
        evaluate({ graph: 'build', group: group?.name, from, kind: 'triple-slash-path', request: reference.fileName, resolved: exists ? rel(fs.realpathSync(target)) : undefined, error: exists ? undefined : 'referenced file missing' }, group);
      }
      for (const reference of sf.typeReferenceDirectives) {
        const result = ts.resolveTypeReferenceDirective(reference.fileName, sf.fileName, options, host, undefined, undefined, reference.resolutionMode).resolvedTypeReferenceDirective;
        if (result?.resolvedFileName) explained.add(fs.realpathSync(result.resolvedFileName));
        const edge = { graph: 'build', group: group?.name, from, kind: 'types-reference', request: reference.fileName, resolved: result?.resolvedFileName ? rel(fs.realpathSync(result.resolvedFileName)) : undefined, error: result ? undefined : 'unresolved type reference' };
        if (group?.platform === 'browser' && /^(?:@types\/)?node$/.test(reference.fileName)) refuse('browser-node', edgeDetail(edge, 'browser source requests Node ambient types'));
        if (evaluate(edge, group) && edge.resolved && !EXTERNAL.test(from) && EXTERNAL.test(edge.resolved)) declared(edge, group, reference.fileName);
      }
    }
    for (const name of parsed.options.types ?? []) {
      const result = ts.resolveTypeReferenceDirective(name, abs(record.tsconfig), options, host).resolvedTypeReferenceDirective;
      if (result?.resolvedFileName) explained.add(fs.realpathSync(result.resolvedFileName));
      else refuse('unresolved', { graph: 'build', from: record.tsconfig, request: name, message: 'types entry does not resolve' });
    }
    for (const sf of program.getSourceFiles()) {
      if (program.isSourceFileDefaultLibrary(sf)) continue;
      if (!explained.has(fs.realpathSync(sf.fileName))) refuse('compiler-unexplained-input', { file: rel(sf.fileName), message: 'TypeScript loaded a file no declared input or recorded edge explains' });
    }
  }

  // ---- runtime graphs (Node resolver / declared browser bundler policy) ----
  const browserResolvers = createBrowserResolvers();
  const runtimeFiles = new Map();
  for (const group of lane.groups) {
    const entries = record.inputs.filter(file => SCANNABLE.test(file) && !DECLARATION.test(file) && groupOf(file) === group);
    const queue = entries.map(file => ({ file, viaOutput: true }));
    const seen = new Set();
    while (queue.length) {
      const { file, viaOutput } = queue.shift();
      const unitKey = file + (viaOutput ? '' : '#in-place');
      if (seen.has(unitKey)) continue;
      seen.add(unitKey);
      const unit = runtimeUnit(file, viaOutput);
      if (!unit) continue;
      const sf = parse(unit.location, unit.text, ts.ScriptKind.JS);
      runtimeFiles.set(unit.location, { file, text: unit.text, own: !EXTERNAL.test(file) });
      const usages = runtimeUsages(sf);
      const format = group.platform === 'node' ? nodeFormat(unit.location, usages) : 'bundled';
      if (format === 'invalid-package-scope' || format === 'ambiguous') refuse('unsupported-module-format', { graph: 'runtime', group: group.name, from: file, message: format === 'ambiguous' ? 'untyped .js mixes module syntax with require' : 'nearest package.json is invalid' });
      if (format === 'commonjs' && usages.esmSyntax) refuse('unsupported-module-format', { graph: 'runtime', group: group.name, from: file, message: 'module syntax in a CommonJS-format file' });
      if (format === 'module' && usages.requireCalls && !usages.declaresRequire) refuse('unsupported-module-format', { graph: 'runtime', group: group.name, from: file, message: 'require in an ES module without a local require binding' });
      for (const item of usages.unsupported) {
        if (EXTERNAL.test(file) && group.platform === 'node') continue; // inert without an AMD loader; disclosed limit
        refuse('unsupported-module-format', { graph: 'runtime', group: group.name, from: file, line: item.line, column: item.column, message: `AMD request (${item.kind}) is not selected` });
      }
      for (const loader of usages.loaders) {
        if (loader.declaredInputsOnly && EXTERNAL.test(file)) continue;
        const trusted = unit.raw ? matchTrusted('dynamic-loader', { from: file, line: loader.line, column: loader.column, text: loader.text }) : undefined;
        if (!trusted) { refuse('unsupported-loader', { graph: 'runtime', group: group.name, from: file, line: loader.line, column: loader.column, message: `${loader.kind}: ${loader.text}` }); continue; }
        for (const target of trusted.targets) {
          if (!inputs.has(target)) { refuse('lane-record-invalid', { from: file, message: `trusted dynamic loader target ${target} is not a declared input` }); continue; }
          evaluate({ graph: 'runtime', group: group.name, from: file, kind: 'trusted-dynamic-loader', request: target, line: loader.line, column: loader.column, resolved: target }, group);
          queue.push({ file: target, viaOutput: true });
        }
      }
      for (const request of usages.requests) {
        const edge = { graph: 'runtime', group: group.name, from: file, kind: request.kind, request: request.request, mode: request.mode, line: request.line, column: request.column, text: request.text, guarded: request.guarded };
        let result = group.platform === 'node' ? nodeResolve(request.request, unit.location, request.mode) : browserResolve(browserResolvers, request.request, unit.location, request.mode);
        if (request.builtinOnly && !result.core) result = { error: 'ERR_UNKNOWN_BUILTIN_MODULE' };
        let viaTarget = false;
        if (!result.resolved && !result.core && !result.ignored && !EXTERNAL.test(file) && result.candidate && plannedOutputs.has(result.candidate)) {
          result = { resolved: plannedOutputs.get(result.candidate), emittedOutput: rel(result.candidate) };
          viaTarget = true;
        }
        Object.assign(edge, { core: result.core, ignored: result.ignored, error: result.error, emittedOutput: result.emittedOutput, resolved: result.resolved && !result.core ? rel(result.resolved) : result.core ? result.resolved : undefined });
        if (edge.core) edge.resolved = undefined, edge.coreModule = result.resolved;
        if (evaluate(edge, group) && edge.resolved && !edge.core) queue.push({ file: edge.resolved, viaOutput: viaTarget });
      }
      for (const asset of usages.assets) {
        const target = path.resolve(path.dirname(unit.location), asset.request);
        const exists = fs.statSync(target, { throwIfNoEntry: false })?.isFile();
        const edge = { graph: 'runtime', group: group.name, from: file, kind: asset.kind, request: asset.request, line: asset.line, column: asset.column, resolved: exists ? rel(fs.realpathSync(target)) : undefined, error: exists ? undefined : 'asset target missing' };
        if (evaluate(edge, group) && edge.resolved && SCANNABLE.test(edge.resolved) && asset.kind === 'worker-path') queue.push({ file: edge.resolved, viaOutput: false });
      }
    }
  }

  function runtimeUnit(file, viaOutput) {
    const physical = abs(file);
    if (DECLARATION.test(file)) { refuse('unsupported-runtime-target', { graph: 'runtime', from: file, message: 'declaration file reached at runtime' }); return undefined; }
    if (TS_SOURCE.test(file) && !EXTERNAL.test(file)) {
      const output = emitted.get(physical);
      if (!output) { refuse('config-invalid', { graph: 'runtime', from: file, message: 'TypeScript runtime source has no emitted JavaScript (not part of the lane program)' }); return undefined; }
      return { location: viaOutput ? output.location : physical, text: output.text, raw: false };
    }
    if (JS_FILE.test(file)) return { location: physical, text: fs.readFileSync(physical, 'utf8'), raw: true };
    if (TS_SOURCE.test(file)) { refuse('unresolved', { graph: 'runtime', from: file, message: 'TypeScript file under node_modules is not runnable (ERR_UNSUPPORTED_NODE_MODULES_TYPE_STRIPPING)' }); return undefined; }
    return undefined; // JSON, .node and other non-module assets are leaves
  }

  // ---- reached externals and syntax ----
  const externalUnits = [...runtimeFiles.entries()].filter(([, v]) => !v.own);
  if (externalUnits.length) {
    const texts = new Map(externalUnits.map(([location, v]) => [location, v.text]));
    const parseOptions = { allowJs: true, noResolve: true, noLib: true, types: [], noEmit: true };
    const host = ts.createCompilerHost(parseOptions, true);
    host.readFile = file => texts.get(path.resolve(file)) ?? ts.sys.readFile(file);
    const syntaxProgram = ts.createProgram({ rootNames: [...texts.keys()], options: parseOptions, host });
    for (const [location, v] of externalUnits) {
      const sf = syntaxProgram.getSourceFile(location);
      const diagnostics = sf ? syntaxProgram.getSyntacticDiagnostics(sf) : [];
      if (!sf || diagnostics.length) refuse('parse-failure', { graph: 'runtime', from: v.file, message: sf ? ts.flattenDiagnosticMessageText(diagnostics[0].messageText, '\n') : 'not parsed' });
    }
  }

  // ---- census of reached lane files and trusted-usage staleness ----
  for (const file of reachedLocal) if (within(file, own) && !inputs.has(file)) refuse('undeclared-local', { file, message: 'graph reaches an undeclared lane file' });
  record.trustedUsages.forEach((trusted, index) => {
    if (!trustedApplied.has(index)) refuse('lane-record-invalid', { file: trusted.file, line: trusted.line, column: trusted.column, message: `stale or mismatched ${trusted.kind} record` });
  });

  return finish();

  function finish() {
    const seen = new Set();
    const unique = refusals.filter(r => { const key = JSON.stringify(r); if (seen.has(key)) return false; seen.add(key); return true; });
    return {
      schemaVersion: 1,
      tool: { name: 'check-boundary', version: TOOL_VERSION, typescript: ts.version, node: process.version },
      lane: { package: record.package, packageRoot: record.packageRoot, standing: lane.standing, policy: lane.policyId, groups: lane.groups.map(g => ({ name: g.name, platform: g.platform, runtimeClasses: g.runtimeClasses })) },
      inventoryBinding: { designLockSha256: binding.designLockSha256, selectedInventory: binding.selectedInventory, inventoryStanding: binding.inventoryStanding, pinsVerified: binding.pinsVerified, acceptanceChain: binding.acceptanceChain,
        inventoryRowsPresentUndeclared: typeof inventoryRowsPresent === 'undefined' ? [] : inventoryRowsPresent.filter(row => !inputs.has(row)), inputsWithoutInventoryRow: typeof unboundInputs === 'undefined' ? [] : unboundInputs },
      topology: typeof topology === 'undefined' ? undefined : topology,
      passed: unique.length === 0,
      refusals: unique,
      trustedUsagesApplied: record.trustedUsages.filter((_, index) => trustedApplied.has(index)),
      edges,
      stats: { edges: edges.length, milliseconds: Math.round(Number(process.hrtime.bigint() - started) / 1e6), maxRssBytes: process.resourceUsage().maxRSS * 1024 },
      sourcePurityQualified: false,
      dependencyClosureQualified: false,
      limits: [
        'Static literal module requests only; no module is executed. Computed loaders are refused unless an exact trusted-usage record matches; eval/Function are refused in lane sources only.',
        'Build graph: TypeScript 6.0.3 resolution with the lane tsconfig (allowJs forced on, emit forced for analysis). It does not prove runtime resolvability.',
        'Node runtime graph: Node 24 non-executing resolution of TypeScript-emitted or materialized JavaScript. Load-time failures other than missing files, directory imports and node_modules type stripping are not modelled.',
        'Browser runtime graph: enhanced-resolve 5.25.1 as a declared bundler policy; the bundler is unselected and bundler plugins/aliases are not modelled.',
        'AMD calls inside materialized dependencies of Node groups are treated as inert (no AMD loader) and are not followed.',
        'Inventory binding verifies design-lock pins only; the acceptance chain is owned by tools/verify_design.py.',
      ],
    };
  }
}

function parseArguments(argv) {
  const usage = 'usage: check-boundary --root DIR --lane-record FILE --design-lock FILE --architecture DIR [--unbound-lane tooling]';
  const keys = ['--root', '--lane-record', '--design-lock', '--architecture', '--unbound-lane'];
  const values = {};
  for (let i = 0; i < argv.length; i += 2) {
    const [key, value] = [argv[i], argv[i + 1]];
    if (!keys.includes(key) || Object.hasOwn(values, key) || typeof value !== 'string' || !value || value.startsWith('--')) throw new LaneError(usage);
    values[key] = value;
  }
  for (const key of keys.slice(0, 4)) if (!values[key]) throw new LaneError(usage);
  return values;
}

export async function main(argv) {
  try {
    const args = parseArguments(argv);
    let record;
    try { record = strictJson(fs.readFileSync(args['--lane-record']), 'lane record'); } catch (error) {
      throw error instanceof LaneError ? error : new LaneError('cannot read lane record: ' + error.message);
    }
    if (!fs.existsSync(args['--design-lock']) || !fs.statSync(args['--architecture'], { throwIfNoEntry: false })?.isDirectory()) throw new LaneError('design lock file and architecture directory must exist');
    const report = await checkBoundary({ root: args['--root'], record, designLock: args['--design-lock'], architecture: args['--architecture'], unboundKind: args['--unbound-lane'] });
    process.stdout.write(JSON.stringify(report, null, 2) + '\n');
    return report.passed ? 0 : 1;
  } catch (error) {
    process.stderr.write('boundary check refused: ' + error.message + '\n');
    return error instanceof LaneError ? 2 : 3;
  }
}

// Verifies acquired registry archives: sha512 against lock integrity, and
// archive contents byte-for-byte against the materialized package trees that
// are executed. Archives not acquired are reported as not verified.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const top = path.resolve(here, '..');
const scratch = path.join(top, 'work', 'archive-extract');
const archives = path.join(here, 'archives');
const sha512 = file => 'sha512-' + crypto.createHash('sha512').update(fs.readFileSync(file)).digest('base64');
const npmLock = JSON.parse(fs.readFileSync(path.join(top, 'baseline/subject-02-trial/package-lock.json'), 'utf8')).packages;
const pnpmLock = fs.readFileSync(path.join(top, 'inputs/pnpm-provision-05/pnpm-lock.yaml'), 'utf8');

const TREES = [
  { archive: 'typescript-6.0.3.tgz', lockKey: 'node_modules/typescript', trees: ['checker/node_modules/typescript', 'baseline/subject-02-trial/node_modules/typescript', 'inputs/pnpm-provision-05/node_modules/.pnpm/typescript@6.0.3/node_modules/typescript'] },
  { archive: 'enhanced-resolve-5.25.1.tgz', lockKey: 'node_modules/enhanced-resolve', trees: ['checker/node_modules/enhanced-resolve', 'baseline/subject-02-trial/node_modules/enhanced-resolve'] },
  { archive: 'graceful-fs-4.2.11.tgz', lockKey: 'node_modules/graceful-fs', trees: ['checker/node_modules/graceful-fs', 'baseline/subject-02-trial/node_modules/graceful-fs'] },
  { archive: 'tapable-2.3.3.tgz', lockKey: 'node_modules/tapable', trees: ['checker/node_modules/tapable', 'baseline/subject-02-trial/node_modules/tapable'] },
  { archive: 'dependency-cruiser-18.3.1.tgz', lockKey: 'node_modules/dependency-cruiser', trees: ['baseline/subject-02-trial/node_modules/dependency-cruiser'] },
];

const listFiles = dir => fs.readdirSync(dir, { withFileTypes: true }).flatMap(e => e.isDirectory() ? listFiles(path.join(dir, e.name)).map(f => path.join(e.name, f)) : [e.name]).sort();
fs.rmSync(scratch, { recursive: true, force: true });
const rows = [];
for (const { archive, lockKey, trees } of TREES) {
  const file = path.join(archives, archive);
  const integrity = sha512(file);
  const extract = path.join(scratch, archive);
  fs.mkdirSync(extract, { recursive: true });
  execFileSync('/usr/bin/tar', ['-xzf', file, '-C', extract]);
  const packed = path.join(extract, 'package');
  const packedFiles = listFiles(packed);
  const row = { archive, sha256: crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex'), sha512: integrity,
    npmLockIntegrity: npmLock[lockKey]?.integrity, matchesNpmLock: npmLock[lockKey]?.integrity === integrity, trees: [] };
  if (archive.startsWith('typescript-')) row.matchesPnpmLock = pnpmLock.includes(`integrity: ${integrity}`);
  for (const tree of trees) {
    const dir = path.join(top, tree);
    if (!fs.existsSync(dir)) { row.trees.push({ tree, present: false }); continue; }
    const actual = listFiles(dir);
    const differences = [...new Set([...packedFiles, ...actual])].filter(rel => {
      const a = path.join(packed, rel), b = path.join(dir, rel);
      return !fs.existsSync(a) || !fs.existsSync(b) || !fs.readFileSync(a).equals(fs.readFileSync(b));
    });
    row.trees.push({ tree, present: true, files: actual.length, archiveFiles: packedFiles.length, identical: differences.length === 0, differences: differences.slice(0, 10) });
  }
  rows.push(row);
}
const notAcquired = Object.keys(npmLock).filter(k => k && !TREES.some(t => t.lockKey === k)).sort();
const result = { schemaVersion: 1, standing: 'archive custody check; network acquisition recorded in provenance/archives/*.registry.json', verified: rows,
  baselineLockPackagesWithoutArchive: notAcquired, note: 'packages listed without archive are verified only as frozen materialized bytes, not against original registry archives' };
fs.mkdirSync(path.join(top, 'results'), { recursive: true });
fs.writeFileSync(path.join(top, 'results/archive-verification.json'), JSON.stringify(result, null, 2) + '\n');
for (const row of rows) console.log(row.archive, 'npmLock', row.matchesNpmLock, 'pnpmLock', row.matchesPnpmLock ?? '-', row.trees.map(t => `${t.tree}:${t.present ? t.identical : 'absent'}`).join(' '));
console.log('without archive:', notAcquired.length);

