// Authors the lane records for the real and missing-lane fixtures. Trusted usages
// are limited to three named usages; their exact positions and file hashes are
// computed from the frozen inputs, and authoring fails if a named usage is absent.
// The written records are reviewed inputs; the checker re-verifies every binding.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const top = path.resolve(here, '../..');
const { parse, runtimeUsages } = await import(path.join(top, 'checker/src/usages.mjs'));

const TYPESCRIPT_JS = 'node_modules/.pnpm/typescript@6.0.3/node_modules/typescript/lib/typescript.js';
function exact(sourcePath, recordPath, predicate, label) {
  const text = fs.readFileSync(path.join(top, sourcePath), 'utf8');
  const usages = runtimeUsages(parse(recordPath, text));
  const matches = [...usages.loaders, ...usages.requests].filter(predicate);
  if (matches.length !== 1) throw new Error(`${label}: expected exactly one usage, found ${matches.length}`);
  const [usage] = matches;
  return { file: recordPath, sha256: crypto.createHash('sha256').update(text).digest('hex'), line: usage.line, column: usage.column, text: usage.text, guarded: usage.guarded };
}

const validate = exact('inputs/staged-control-generation-02/tools/contracts/validate-schemas.cjs', 'tools/contracts/validate-schemas.cjs',
  u => u.kind === 'computed-require' && u.text === 'require(file)', 'validate-schemas require(file)');
const pluginLoader = exact(`inputs/pnpm-provision-05/${TYPESCRIPT_JS}`, `tools/contracts/${TYPESCRIPT_JS}`,
  u => u.kind === 'computed-require' && u.text === 'require(modulePath)', 'typescript.js require(modulePath)');
const sourceMap = exact(`inputs/pnpm-provision-05/${TYPESCRIPT_JS}`, `tools/contracts/${TYPESCRIPT_JS}`,
  u => u.request === 'source-map-support', 'typescript.js source-map-support');
if (!sourceMap.guarded) throw new Error('source-map-support request is not guarded by try');

const drop = ({ guarded, ...usage }) => usage;
const records = {
  contracts: {
    schemaVersion: 2, package: 'tooling', packageRoot: 'tools/contracts', manifest: 'tools/contracts/package.json', tsconfig: 'tools/contracts/tsconfig.json',
    inputs: ['tools/contracts/generate-ts.cjs', 'tools/contracts/render-types.cjs', 'tools/contracts/runtime/exact-json.ts', 'tools/contracts/runtime/patterns.ts', 'tools/contracts/runtime/schema.ts', 'tools/contracts/validate-schemas.cjs'],
    packageManager: { kind: 'pnpm', lockfile: 'tools/contracts/pnpm-lock.yaml' },
    trustedUsages: [
      { kind: 'dynamic-loader', ...drop(validate), targets: ['tools/contracts/runtime/exact-json.ts', 'tools/contracts/runtime/patterns.ts', 'tools/contracts/runtime/schema.ts'],
        reason: 'Loads the scratch CommonJS module validate-schemas.cjs writes from a TypeScript transpile of exactly these declared runtime sources (import lines stripped). Targets are analyzed as lane inputs.' },
      { kind: 'dynamic-loader', ...drop(pluginLoader), targets: [],
        reason: 'TypeScript 6.0.3 sys.require (resolveJSModule) for compiler plugins. Not called by generate-ts/render-types/validate-schemas; no targets are analyzed. Owner decision required before integration.' },
      { kind: 'optional-unresolved', ...drop(sourceMap), request: 'source-map-support', mode: 'require',
        reason: 'TypeScript 6.0.3 tryEnableSourceMapsForHost: optional source-map-support install inside try/catch; the package is intentionally absent from the lane closure.' },
    ],
  },
  provider: {
    schemaVersion: 2, package: 'typescript-provider', packageRoot: 'providers/typescript', manifest: 'providers/typescript/package.json', tsconfig: 'providers/typescript/tsconfig.json',
    inputs: ['providers/typescript/src/generated/protocol.ts', 'providers/typescript/src/index.ts'],
    packageManager: { kind: 'fixture-unlocked', lockfile: null }, trustedUsages: [],
  },
  report: {
    schemaVersion: 2, package: 'report', packageRoot: 'apps/report', manifest: 'apps/report/package.json', tsconfig: 'apps/report/tsconfig.json',
    inputs: ['apps/report/src/generated/report.ts', 'apps/report/src/index.ts'],
    packageManager: { kind: 'fixture-unlocked', lockfile: null }, trustedUsages: [],
  },
};
for (const [name, record] of Object.entries(records)) fs.writeFileSync(path.join(here, `${name}.lane-record.json`), JSON.stringify(record, null, 2) + '\n');
console.log(JSON.stringify(records.contracts.trustedUsages.map(u => `${u.kind} ${u.file}:${u.line}:${u.column} ${u.text}`), null, 1));

// Real-lane runs. contracts = the staged control-generation-02 tools/contracts
// sources plus the pnpm 11.10.0 isolated materialization of typescript@6.0.3
// (inputs/pnpm-provision-05) and a trial-authored tsconfig. provider/report are
// honest missing-lane fixtures: the staged generated bindings are real, the
// package.json, tsconfig and a small index are fixtures. Each run is measured with
// /usr/bin/time -l (wall seconds, maximum resident set size of the process tree).
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const top = path.resolve(here, '../..');
const work = path.join(top, 'work', 'real-lanes');
const tmp = path.join(top, 'work', 'tmp');
fs.mkdirSync(tmp, { recursive: true });
const env = { ...process.env, TMPDIR: tmp };
const staged = path.join(top, 'inputs/staged-control-generation-02');
const pnpm = path.join(top, 'inputs/pnpm-provision-05');
const sha = file => crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
const copy = (from, to) => { fs.mkdirSync(path.dirname(to), { recursive: true }); fs.cpSync(from, to, { recursive: true, verbatimSymlinks: true }); };
const write = (file, text) => { fs.mkdirSync(path.dirname(file), { recursive: true }); fs.writeFileSync(file, text); };

fs.rmSync(work, { recursive: true, force: true });
const manifestComparison = Object.fromEntries(['package.json', 'pnpm-lock.yaml', 'pnpm-workspace.yaml'].map(name => [name, sha(path.join(staged, 'tools/contracts', name)) === sha(path.join(pnpm, name))]));
if (!Object.values(manifestComparison).every(Boolean)) throw new Error('pnpm materialization was not produced from the staged manifest/lock bytes: ' + JSON.stringify(manifestComparison));

function assembleContracts(root, tsconfigText) {
  copy(path.join(staged, 'tools/contracts'), path.join(root, 'tools/contracts'));
  copy(path.join(pnpm, 'node_modules'), path.join(root, 'tools/contracts/node_modules'));
  write(path.join(root, 'tools/contracts/tsconfig.json'), tsconfigText);
}
const roots = {
  contracts: path.join(work, 'contracts/root'),
  provider: path.join(work, 'provider/root'),
  report: path.join(work, 'report/root'),
  'contracts-baseline': path.join(work, 'contracts-baseline/root'),
};
assembleContracts(roots.contracts, fs.readFileSync(path.join(here, 'contracts.tsconfig.json'), 'utf8'));
copy(path.join(staged, 'providers/typescript/src/generated/protocol.ts'), path.join(roots.provider, 'providers/typescript/src/generated/protocol.ts'));
write(path.join(roots.provider, 'providers/typescript/package.json'), JSON.stringify({ name: '@opensip/typescript-provider', version: '0.0.0', private: true, type: 'module' }, null, 2) + '\n');
write(path.join(roots.provider, 'providers/typescript/tsconfig.json'), JSON.stringify({ compilerOptions: { target: 'ES2022', module: 'NodeNext', moduleResolution: 'NodeNext', types: [], strict: true, noEmit: true }, include: ['src/**/*.ts'] }, null, 2) + '\n');
write(path.join(roots.provider, 'providers/typescript/src/index.ts'), 'import type { Control3Root } from "./generated/protocol.js";\nexport function describe(root: Control3Root): string {\n  return typeof root;\n}\n');
copy(path.join(staged, 'apps/report/src/generated/report.ts'), path.join(roots.report, 'apps/report/src/generated/report.ts'));
write(path.join(roots.report, 'apps/report/package.json'), JSON.stringify({ name: '@opensip/report', version: '0.0.0', private: true, type: 'module' }, null, 2) + '\n');
write(path.join(roots.report, 'apps/report/tsconfig.json'), JSON.stringify({ compilerOptions: { target: 'ES2022', module: 'ESNext', moduleResolution: 'Bundler', lib: ['ES2022', 'DOM'], types: [], strict: true, noEmit: true }, include: ['src/**/*.ts'] }, null, 2) + '\n');
write(path.join(roots.report, 'apps/report/src/index.ts'), 'import { createReportShapeRegistry } from "./generated/report.js";\nexport const registry = createReportShapeRegistry();\n');
assembleContracts(roots['contracts-baseline'], fs.readFileSync(path.join(top, 'inputs/review-02/evidence/product-smoke-reviewer-tsconfig.json'), 'utf8'));

function measured(args) {
  const child = spawnSync('/usr/bin/time', ['-l', process.execPath, ...args], { encoding: 'utf8', env, maxBuffer: 512 * 1024 * 1024 });
  const wall = Number(/([\d.]+) real/.exec(child.stderr)?.[1]);
  const rss = Number(/(\d+)\s+maximum resident set size/.exec(child.stderr)?.[1]);
  let report = null;
  try { report = JSON.parse(child.stdout); } catch { /* reported below */ }
  return { status: child.status, wallSeconds: wall, maxRssBytes: rss, report, stderr: child.stderr.split('\n').filter(line => !/^\s+\d+\s/.test(line) && !/real/.test(line)).join('\n').slice(0, 800) };
}

const bin = path.join(top, 'checker/bin/check-boundary.mjs');
const common = ['--design-lock', path.join(top, 'inputs/product/design-lock.json'), '--architecture', path.join(top, 'inputs/architecture')];
const results = {};
for (const lane of ['contracts', 'provider', 'report']) {
  const record = path.join(here, `${lane}.lane-record.json`);
  const run = measured([bin, '--root', roots[lane], '--lane-record', record, ...common, ...(lane === 'contracts' ? ['--unbound-lane', 'tooling'] : [])]);
  const r = run.report;
  results[lane] = {
    candidate: 'author-03 check-boundary', status: run.status, passed: r?.passed ?? null, standing: r?.lane?.standing, topology: r?.topology,
    refusals: r?.refusals ?? [], trustedUsagesApplied: (r?.trustedUsagesApplied ?? []).map(u => ({ kind: u.kind, file: u.file, line: u.line, text: u.text, targets: u.targets })),
    edges: r?.edges?.length ?? 0, edgesByGraph: (r?.edges ?? []).reduce((acc, e) => ({ ...acc, [`${e.graph}/${e.group ?? '-'}`]: (acc[`${e.graph}/${e.group ?? '-'}`] ?? 0) + 1 }), {}),
    inventoryRowsPresentUndeclared: r?.inventoryBinding?.inventoryRowsPresentUndeclared, inputsWithoutInventoryRow: r?.inventoryBinding?.inputsWithoutInventoryRow,
    checkerMilliseconds: r?.stats?.milliseconds, wallSeconds: run.wallSeconds, maxRssBytes: run.maxRssBytes, stderr: run.stderr,
  };
}
