fs.mkdirSync(resultsDir, { recursive: true });
const queue = Object.entries(MUTANTS).filter(([name]) => !only || only.test(name));
await Promise.all(Array.from({ length: concurrency }, async () => {
  while (queue.length) {
    const [name, site] = queue.shift();
    const outcome = await run(name, build(name, site));
    fs.writeFileSync(path.join(resultsDir, name + '.json'), JSON.stringify(outcome, null, 2) + '\n');
