// Freeze manifest for author-03. Records every frozen entry (type, octal mode,
// bytes, sha256, symlink target) grouped by role, the materialized tool closures
// keyed to their locks and archive custody, and the pinned runtime by hash.
// Scratch (work/) and launcher files are excluded and listed as excluded.
//
// usage: node freeze-manifest.mjs            write freeze-manifest.json
//        node freeze-manifest.mjs --verify   compare the tree (except results/) to it
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const top = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const OUTPUT = 'freeze-manifest.json';
const LAUNCHER = ['launch-public.py', 'process.json', 'prompt.md', 'public-events.jsonl', 'result.json', 'response.json', 'final-response.md', 'process-completion.json'];
const EXCLUDED_DIRS = ['work'];
const sha256 = data => crypto.createHash('sha256').update(data).digest('hex');

function walk(relative = '', rows = []) {
  for (const name of fs.readdirSync(path.join(top, relative)).sort()) {
    const rel = relative ? `${relative}/${name}` : name;
    if (!relative && (EXCLUDED_DIRS.includes(name) || LAUNCHER.includes(name) || name === OUTPUT)) continue;
    const abs = path.join(top, rel);
    const stat = fs.lstatSync(abs);
    const mode = (stat.mode & 0o7777).toString(8);
    if (stat.isSymbolicLink()) rows.push({ path: rel, type: 'symlink', mode, target: fs.readlinkSync(abs) });
    else if (stat.isDirectory()) { rows.push({ path: rel, type: 'directory', mode }); walk(rel, rows); }
    else if (stat.isFile()) rows.push({ path: rel, type: 'file', mode, bytes: stat.size, sha256: sha256(fs.readFileSync(abs)) });
    else rows.push({ path: rel, type: 'other', mode });
  }
  return rows;
}

const groupOf = rel =>
  rel.startsWith('checker/node_modules') ? 'checker-tool-closure'
  : rel.startsWith('checker/') || rel === 'checker' ? 'subject-checker'
  : rel.startsWith('harness/') || rel === 'harness' || /^(comparison|selection-proposal|README)\.md$/.test(rel) ? 'subject-harness-and-reports'
  : rel.startsWith('baseline/subject-02-trial/node_modules') ? 'baseline-tool-closure'
  : rel.startsWith('baseline') ? 'baseline-candidate'
  : rel.startsWith('inputs') ? 'executed-inputs'
  : rel.startsWith('provenance') ? 'provenance'
  : rel.startsWith('results') ? 'results'
  : 'other';

function closure(dir, lockPackages, archives) {
  const rows = walk(dir).filter(r => r.type !== 'directory');
  const packages = Object.entries(lockPackages).map(([key, meta]) => {
    const prefix = `${dir}/${key}/`.replace(`${dir}/node_modules/`, `${dir}/node_modules/`);
    const base = `${dir}/${key.replace(/^node_modules\//, 'node_modules/')}/`;
    const tree = rows.filter(r => r.path.startsWith(base) && !r.path.slice(base.length).includes('node_modules/'));
    return { package: key, version: meta.version, lockIntegrity: meta.integrity, files: tree.length,
      treeSha256: sha256(tree.map(r => `${r.type}\0${r.path.slice(base.length)}\0${r.mode}\0${r.sha256 ?? r.target}`).join('\n')),
      archive: archives[key] ?? 'not acquired: verified only as frozen materialized bytes' };
  });
  return { root: dir, entries: rows.length, bytes: rows.reduce((n, r) => n + (r.bytes ?? 0), 0), symlinks: rows.filter(r => r.type === 'symlink').map(r => ({ path: r.path, target: r.target })), packages };
}

const archiveResult = JSON.parse(fs.readFileSync(path.join(top, 'results/archive-verification.json'), 'utf8'));
const archiveByKey = Object.fromEntries(archiveResult.verified.map(v => [`node_modules/${v.archive.replace(/-\d+\.\d+\.\d+\.tgz$/, '')}`, { archive: `provenance/archives/${v.archive}`, sha512: v.sha512, matchesLock: v.matchesNpmLock, treesIdentical: v.trees.filter(t => t.present).every(t => t.identical) }]));
const npmLock = JSON.parse(fs.readFileSync(path.join(top, 'baseline/subject-02-trial/package-lock.json'), 'utf8')).packages;
const checkerPackages = Object.fromEntries(['typescript', 'enhanced-resolve', 'graceful-fs', 'tapable'].map(name => [`node_modules/${name}`, npmLock[`node_modules/${name}`]]));

if (process.argv.includes('--verify')) {
  const frozen = JSON.parse(fs.readFileSync(path.join(top, OUTPUT), 'utf8'));
  const current = new Map(walk().filter(r => !r.path.startsWith('results')).map(r => [r.path, r]));
  const expected = new Map(frozen.entries.filter(r => !r.path.startsWith('results')).map(r => [r.path, r]));
  const problems = [];
  for (const [p, row] of expected) {
    const now = current.get(p);
    if (!now) problems.push(`missing ${p}`);
    else if (JSON.stringify({ ...now, group: row.group }) !== JSON.stringify(row)) problems.push(`changed ${p}`);
  }
  for (const p of current.keys()) if (!expected.has(p)) problems.push(`unexpected ${p}`);
  process.stdout.write(JSON.stringify({ verified: expected.size, problems: problems.slice(0, 50), problemCount: problems.length }) + '\n');
  process.exitCode = problems.length ? 1 : 0;
} else {
  const entries = walk().map(r => ({ ...r, group: groupOf(r.path) }));
  const nodeBinary = process.execPath;
  const manifest = {
    schemaVersion: 1,
    standing: 'author-03 freeze candidate for root freezing and independent review; not an acceptance record',
    root: top,
    pinnedRuntime: { node: process.version, path: nodeBinary, sha256: sha256(fs.readFileSync(fs.realpathSync(nodeBinary))), systemTools: ['/usr/bin/tar (archive extraction)', '/usr/bin/time (real-lane measurement)'] },
    excluded: { scratch: EXCLUDED_DIRS.map(d => d + '/'), launcher: LAUNCHER.filter(f => fs.existsSync(path.join(top, f))) },
    counts: entries.reduce((acc, r) => ({ ...acc, [r.group]: (acc[r.group] ?? 0) + 1 }), {}),
