  walk(path.join(top, dir));
  return { files, bytes, symlinks };
};
const countPackages = dir => fs.readdirSync(path.join(top, dir)).filter(n => !n.startsWith('.')).flatMap(n => n.startsWith('@') ? fs.readdirSync(path.join(top, dir, n)).map(m => `${n}/${m}`) : [n]).length;

